mA7 = [im(f"The number of integers between {a} and {b} (not counting them) that are greater than 0 is:", max(0, b - 1), "Count the positive integers up to b-1.", offs=(1, -1, 2, 3)) for a, b in [(-6, 5), (-4, 8), (-9, 11), (-2, 6)]]
